"""Database connection pool and query execution."""

import sqlite3
import threading


_pool = None
_lock = threading.Lock()


class ConnectionPool:
    def __init__(self, db_path, max_connections=5):
        self.db_path = db_path
        self.max_connections = max_connections
        self._connections = []
        self._in_use = set()

    def acquire(self):
        with _lock:
            for conn in self._connections:
                if conn not in self._in_use:
                    self._in_use.add(conn)
                    return conn
            if len(self._connections) < self.max_connections:
                conn = sqlite3.connect(self.db_path)
                conn.row_factory = sqlite3.Row
                self._connections.append(conn)
                self._in_use.add(conn)
                return conn
        raise RuntimeError("Connection pool exhausted")

    def release(self, conn):
        with _lock:
            self._in_use.discard(conn)

    def close_all(self):
        with _lock:
            for conn in self._connections:
                conn.close()
            self._connections.clear()
            self._in_use.clear()


def init_pool(db_path, max_connections=5):
    global _pool
    _pool = ConnectionPool(db_path, max_connections)
    return _pool


def get_connection():
    if _pool is None:
        raise RuntimeError("Database pool not initialized. Call init_pool() first.")
    return _pool.acquire()


def release_connection(conn):
    if _pool is not None:
        _pool.release(conn)


def execute_query(query, params=None):
    conn = get_connection()
    try:
        cursor = conn.execute(query, params or ())
        if query.strip().upper().startswith("SELECT"):
            rows = cursor.fetchall()
            return [dict(row) for row in rows]
        else:
            conn.commit()
            return cursor.rowcount
    finally:
        release_connection(conn)


def execute_many(query, param_list):
    conn = get_connection()
    try:
        cursor = conn.executemany(query, param_list)
        conn.commit()
        return cursor.rowcount
    finally:
        release_connection(conn)


class DatabaseSession:
    """Context manager for database transactions."""

    def __init__(self):
        self.conn = None

    def __enter__(self):
        self.conn = get_connection()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.conn is not None:
            if exc_type is not None:
                self.conn.rollback()
            else:
                self.conn.commit()
            release_connection(self.conn)
            self.conn = None
        return False

    def execute(self, query, params=None):
        return self.conn.execute(query, params or ())

    def fetchall(self, query, params=None):
        cursor = self.conn.execute(query, params or ())
        return [dict(row) for row in cursor.fetchall()]

