from typing import Any, TypeVar

RegistryType = TypeVar("RegistryType", bound="MetricBase")


class MetricBase:
    def to_dict(self) -> dict[str, Any]:
        pass


class Counter(MetricBase):
    def __init__(self, name: str, description: str = "") -> None:
        self.name = name
        self.description = description
        self._value: int = 0

    def inc(self, amount: int = 1) -> None:
        self._value += amount

    def value(self) -> int:
        return self._value

    def reset(self) -> None:
        self._value = 0

    def to_dict(self) -> dict[str, Any]:
        return {"name": self.name, "type": "counter", "value": self._value}


class Gauge(MetricBase):
    def __init__(self, name: str, description: str = "") -> None:
        self.name = name
        self.description = description
        self._value: float = 0

    def set(self, value: float) -> None:
        self._value = value

    def inc(self, amount: float = 1) -> None:
        self._value += amount

    def dec(self, amount: float = 1) -> None:
        self._value -= amount

    def value(self) -> float:
        return self._value

    def to_dict(self) -> dict[str, Any]:
        return {"name": self.name, "type": "gauge", "value": self._value}


class Histogram(MetricBase):
    def __init__(
        self,
        name: str,
        description: str = "",
        buckets: list[float] | None = None,
    ) -> None:
        self.name = name
        self.description = description
        self.buckets = buckets or [0.01, 0.05, 0.1, 0.25, 0.5, 1.0, 5.0, 10.0]
        self._observations: list[float] = []

    def observe(self, value: float) -> None:
        self._observations.append(value)

    def count(self) -> int:
        return len(self._observations)

    def sum(self) -> float:
        return sum(self._observations) if self._observations else 0.0

    def avg(self) -> float:
        if not self._observations:
            return 0.0
        return self.sum() / self.count()

    def percentile(self, p: float) -> float:
        if not self._observations:
            return 0.0
        sorted_obs = sorted(self._observations)
        idx = int(len(sorted_obs) * p / 100)
        return sorted_obs[min(idx, len(sorted_obs) - 1)]

